use serde::Deserialize;use serde_json::{json,Value};use std::{env,fs,io::{self,Read,Write},path::PathBuf};#[derive(Deserialize)]#[serde(rename_all="camelCase")]struct M{#[serde(rename="type")]t:String,#[serde(default)]request_id:Option<String>,#[serde(flatten)]x:Value}fn d()->PathBuf{PathBuf::from(env::var_os("LOCALAPPDATA").unwrap()).join("WordBatchTool/integration")}fn main(){let mut l=[0;4];io::stdin().read_exact(&mut l).unwrap();let mut b=vec![0;u32::from_le_bytes(l)as usize];io::stdin().read_exact(&mut b).unwrap();let m:M=serde_json::from_slice(&b).unwrap();let v=if m.t=="get-pending-document-context-request"{let p=d().join("bridge-request.json");if p.exists(){json!({"ok":true,"pending":true,"request":serde_json::from_slice::<Value>(&fs::read(p).unwrap()).unwrap()})}else{json!({"ok":true,"pending":false})}}else{let r:Value=serde_json::from_slice(&fs::read(d().join("bridge-request.json")).unwrap()).unwrap();let mut o=m.x;let q=o.as_object_mut().unwrap();q.insert("requestId".into(),json!(m.request_id.unwrap()));q.insert("type".into(),json!(if r["type"]=="bridge-health-check"{"bridge-health-check-result"}else{"current-document-context-result"}));q.insert("ok".into(),json!(true));fs::write(d().join("bridge-response.json"),serde_json::to_vec(&o).unwrap()).unwrap();json!({"ok":true})};let b=serde_json::to_vec(&v).unwrap();let mut o=io::stdout();o.write_all(&(b.len()as u32).to_le_bytes()).unwrap();o.write_all(&b).unwrap();}
